"""Owner-spec grant research and drafting capabilities M3 rows 180-210."""
from __future__ import annotations
from typing import Any
ROWS=dict(enumerate('''Google Docs access|Google Sheets access|Report generation|Microeconomics idea research|Macroeconomics idea research|500,000-field idea taxonomy target|Continuous public-source research|Venture advice corpus|Existing venture and company analysis|Business stories and founder analysis|Failure-case analysis|Prediction-market analysis|Stock-market research tools|1,000,000-variable analysis target|Gemini guideline-theme analysis|arXiv literature search|PubMed literature search|Grant-specific database search|1,000+ funded-proposal corpus target|Claude full-proposal drafting|GPT-4 clarity/impact/feasibility critique|Revision from critique|DOCX export|PDF export|Budget template engine|Current market-rate lookup|Budget table output|Vector similarity against funded proposals|Language/structure gap analysis|Useful tool and extension discovery|Twenty-part grant workflow target'''.split('|'),180))
class ExpandedM3Error(ValueError):pass
PROFILES={180:('docs_access',['document_ids','access_scope'],['account','permission','retrieve','revision','citation']),181:('sheets_access',['spreadsheet_ids','ranges'],['account','permission','retrieve_values','types','provenance']),182:('report',['question','evidence'],['outline','claims','citations','tables','limitations','review']),183:('micro_research',['topic','public_sources'],['agents','incentives','constraints','equilibrium','welfare','evidence']),184:('macro_research',['topic','public_sources'],['output','inflation','employment','fiscal','monetary','external','evidence']),185:('taxonomy_target',['seed_fields','target'],['hierarchy','deduplicate','definitions','coverage','count_gap']),186:('continuous_research',['queries','public_sources'],['schedule_proposal','source_policy','dedupe','change_detection','no_monitor_started']),187:('advice_corpus',['documents'],['rights','ingest','chunk','metadata','retrieval']),188:('venture_analysis',['companies','evidence'],['business_model','market','traction','team','risks','comparables']),189:('founder_stories',['stories'],['timeline','decisions','context','outcomes','selection_bias']),190:('failure_cases',['cases'],['failure_mode','causal_evidence','counterfactual','lesson','survivorship_bias']),191:('prediction_markets',['markets'],['question','resolution','probability','liquidity','calibration','limits']),192:('stock_research',['securities','sources'],['filings','fundamentals','valuation_inputs','risks','market_data','not_advice']),193:('variable_target',['variables','target'],['schema','types','lineage','quality','coverage_gap']),194:('guideline_themes',['guidelines','model'],['sections','themes','citations','conflicts','human_check']),195:('arxiv_search',['query'],['query','results','metadata','abstracts','dedupe']),196:('pubmed_search',['query'],['query','results','mesh','abstracts','dedupe']),197:('grant_database',['query','databases'],['eligibility_filters','results','deadlines','official_links','dedupe']),198:('funded_corpus',['award_records','target'],['official_source','unique_awards','metadata','count_gap','no_invention']),199:('proposal_draft',['call','applicant_facts','model'],['requirements','outline','sections','citations','needs_input','review']),200:('proposal_critique',['proposal','criteria','model'],['clarity','impact','feasibility','evidence','prioritized_actions']),201:('revision',['proposal','critique'],['issue_map','edits','claim_lock','diff','unresolved']),202:('docx_export',['document','styles'],['validate','render_plan','headings','tables','accessibility','approval']),203:('pdf_export',['document','layout'],['validate','render_plan','pagination','fonts','accessibility','approval']),204:('budget_template',['categories','rules'],['line_schema','formulas','indirects','justification','validation']),205:('market_rates',['items','sources'],['geography','date','unit','rate','source','uncertainty']),206:('budget_table',['line_items','currency'],['subtotal','indirects','total','rounding','justification']),207:('vector_similarity',['proposal','funded_proposals'],['permission','embed','rank','citations','similarity_not_success']),208:('gap_analysis',['proposal','references'],['language_patterns','structure','missing_evidence','differences','no_copying']),209:('tool_discovery',['needs','candidates'],['capabilities','publisher','permissions','security','fit','approval']),210:('workflow_target',['parts'],['twenty_parts','dependencies','owners','artifacts','gates','completion'])}
def run(row:int,p:dict[str,Any])->dict[str,Any]:
 if row not in ROWS:raise ExpandedM3Error('unsupported row')
 mode,required,stages=PROFILES[row];missing=[k for k in required if p.get(k) in (None,[],{})]
 if missing:raise ExpandedM3Error('missing required inputs: '+', '.join(missing))
 sources=p.get('sources',[])
 if not sources or any(not x.get('source_id') or not x.get('observed_at') for x in sources):raise ExpandedM3Error('timestamped source provenance required')
 if row==185 and int(p['target'])!=500000:raise ExpandedM3Error('taxonomy target must be 500000')
 if row==193 and int(p['target'])!=1000000:raise ExpandedM3Error('variable target must be 1000000')
 if row==198 and int(p['target'])<1000:raise ExpandedM3Error('funded corpus target must be at least 1000')
 if row==210 and len(p['parts'])!=20:raise ExpandedM3Error('workflow requires exactly twenty parts')
 ev=p.get('workflow_evidence',p.get('evidence',{}));ev=ev if isinstance(ev,dict) else {};workflow=[{'stage':s,'evidence':ev.get(s),'status':'supported' if ev.get(s) not in (None,[],{}) else 'pending'} for s in stages]
 metrics={}
 if row in (185,193,198):
  actual=len(p.get('seed_fields',p.get('variables',p.get('award_records',[]))));target=int(p['target']);metrics={'target':target,'actual':actual,'gap':max(0,target-actual),'target_met':actual>=target}
 if row==206:
  amounts=[float(x['quantity'])*float(x['unit_rate']) for x in p['line_items']];metrics={'subtotal':sum(amounts),'currency':p['currency']}
 return {'row_id':row,'requirement':ROWS[row],'mode':mode,'workflow':workflow,'pending':[x['stage'] for x in workflow if x['status']=='pending'],'metrics':metrics,'sources':sources,'status':'reviewable_research_or_draft','external_effects':[],'boundary':'Use permissioned documents and public/legal sources with citations. Never invent scale, awards, rates, applicant facts, access, results or completion. Exports, account access, monitoring and external actions remain proposals pending source validation and approval.'}
